// constat:template id=go-mutation version=80 sha256=fe30140fdbbe701a17207a8e0a7a2775d434b78f472aa051f619f14dbcf94407
// Generated by DoneMark's onboarding pull request. Produces the "constat-check-report-mutation"
// workflow artifact: does a check that runs a line this change added or altered actually NOTICE
// that line being wrong?
//
// The fourth proof. It breaks, one line at a time, only what this change's own diff introduced —
// nothing outside it is ever touched, however long the run goes — reruns the suite, and reads the
// result back through the SAME reporter CI publishes, so a mutant's verdict is in the same words
// as every other check on the record. Every mutant's edit is reverted before the next one is even
// planned, and a run that would exceed its time or mutant-count budget stops before starting one
// more and says in the published report how much of the plan it actually covered.
//
// Usage: go run .github/scripts/constat-go-mutation.go <base-ref> <outputFile>
//   env MUTATION_MAX_MUTANTS    (default 6)   — the mutant-count cap.
//   env MUTATION_BUDGET_SECONDS (default 240) — the wall-clock cap for the whole mutation loop.
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"
)

type check struct {
	Name   string  `json:"name"`
	Status string  `json:"status"`
	File   *string `json:"file"`
}

type mutant struct {
	File        string  `json:"file"`
	Line        int     `json:"line"`
	Description string  `json:"description"`
	Checks      []check `json:"checks"`
}

type mutationReport struct {
	Schema           string   `json:"schema"`
	PlannedMutants   int      `json:"plannedMutants"`
	AttemptedMutants int      `json:"attemptedMutants"`
	StoppedEarly     bool     `json:"stoppedEarly"`
	BudgetSeconds    int      `json:"budgetSeconds"`
	Mutants          []mutant `json:"mutants"`
}

type swap struct{ from, to string }

// Go has one equality pair and no strict variant, so the list is shorter than the Elixir one and
// every entry is an operator a change can plausibly get the wrong way round.
var operators = []swap{
	{"==", "!="}, {"!=", "=="}, {">=", "<"}, {"<=", ">"}, {" && ", " || "}, {" || ", " && "},
}

var hunkHeader = regexp.MustCompile(`^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@`)
var ifLine = regexp.MustCompile(`^(\s*)if (.+) \{\s*$`)

func git(args ...string) (string, error) {
	out, err := exec.Command("git", args...).CombinedOutput()
	return string(out), err
}

func addedLines(patch string) []int {
	lines := []int{}
	at := 0
	inHunk := false
	for _, raw := range strings.Split(patch, "\n") {
		if match := hunkHeader.FindStringSubmatch(raw); match != nil {
			at, _ = strconv.Atoi(match[1])
			inHunk = true
			continue
		}
		if !inHunk || strings.HasPrefix(raw, "+++") || strings.HasPrefix(raw, "---") {
			continue
		}
		switch {
		case strings.HasPrefix(raw, "+"):
			lines = append(lines, at)
			at++
		case strings.HasPrefix(raw, "-"), strings.HasPrefix(raw, "\\"):
		default:
			at++
		}
	}
	return lines
}

/** What this script knows how to break on one line, and what it would say about having done it. */
func describeMutation(line string) (string, string) {
	trimmed := strings.TrimSpace(line)
	if trimmed == "" || strings.HasPrefix(trimmed, "//") {
		return "", ""
	}
	for _, op := range operators {
		if strings.Contains(line, op.from) {
			mutated := strings.Replace(line, op.from, op.to, 1)
			if mutated != line {
				return fmt.Sprintf("inverted the operator: '%s' became '%s'", strings.TrimSpace(op.from), strings.TrimSpace(op.to)), mutated
			}
		}
	}
	if trimmed == "return true" || trimmed == "return false" {
		flipped := "return false"
		if trimmed == "return false" {
			flipped = "return true"
		}
		indent := line[:len(line)-len(strings.TrimLeft(line, " \t"))]
		return "flipped a fixed boolean return value", indent + flipped
	}
	if match := ifLine.FindStringSubmatch(line); match != nil && !strings.Contains(match[2], "!") && !strings.Contains(match[2], ":=") {
		return "negated the whole condition", fmt.Sprintf("%sif !(%s) {", match[1], match[2])
	}
	return "", ""
}

/** The suite, run once, read back through the reporter CI itself publishes. */
func checksAfter() []check {
	raw := ".constat/check-report-mutant/raw.json"
	report := ".constat/check-report-mutant/checks.json"
	os.MkdirAll(filepath.Dir(raw), 0o755)
	os.Remove(report)
	handle, err := os.Create(raw)
	if err != nil {
		return nil
	}
	run := exec.Command("go", "test", "-json", "./...")
	run.Stdout = handle
	run.Stderr = os.Stderr
	run.Run()
	handle.Close()
	translate := exec.Command("go", "run", ".github/scripts/constat-go-report.go", raw, report)
	translate.Stderr = os.Stderr
	if err := translate.Run(); err != nil {
		return nil
	}
	body, err := os.ReadFile(report)
	if err != nil {
		return nil
	}
	var published struct {
		Checks []check `json:"checks"`
	}
	if err := json.Unmarshal(body, &published); err != nil {
		return nil
	}
	return published.Checks
}

func write(output string, report mutationReport) {
	if report.Mutants == nil {
		report.Mutants = []mutant{}
	}
	var encoded bytes.Buffer
	writer := json.NewEncoder(&encoded)
	writer.SetEscapeHTML(false)
	writer.SetIndent("", "  ")
	if err := writer.Encode(report); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	os.MkdirAll(filepath.Dir(output), 0o755)
	if err := os.WriteFile(output, encoded.Bytes(), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func main() {
	if len(os.Args) < 3 {
		fmt.Fprintln(os.Stderr, "usage: constat-go-mutation.go <base-ref> <outputFile>")
		os.Exit(2)
	}
	baseRef, output := os.Args[1], os.Args[2]
	maxMutants := 6
	if said := os.Getenv("MUTATION_MAX_MUTANTS"); said != "" {
		if n, err := strconv.Atoi(said); err == nil {
			maxMutants = n
		}
	}
	budgetSeconds := 240
	if said := os.Getenv("MUTATION_BUDGET_SECONDS"); said != "" {
		if n, err := strconv.Atoi(said); err == nil {
			budgetSeconds = n
		}
	}

	// ---- 1. Which lines did this change add or alter? Git's own diff, never a wider scan. ----
	if out, err := git("fetch", "--no-tags", "origin", baseRef); err != nil {
		fmt.Fprintf(os.Stderr, "could not fetch %s: %s\n", baseRef, out)
		os.Exit(1)
	}
	mergeBaseOut, err := git("merge-base", "FETCH_HEAD", "HEAD")
	if err != nil {
		fmt.Fprintf(os.Stderr, "could not find the merge base: %s\n", mergeBaseOut)
		os.Exit(1)
	}
	mergeBase := strings.TrimSpace(mergeBaseOut)
	nameStatus, err := git("diff", "--name-status", "--diff-filter=ACMR", mergeBase, "HEAD")
	if err != nil {
		fmt.Fprintf(os.Stderr, "could not read the diff: %s\n", nameStatus)
		os.Exit(1)
	}

	// ---- 2. Which of those lines does this script know how to break? ----
	planned := []mutant{}
	candidates := 0
	for _, row := range strings.Split(strings.TrimSpace(nameStatus), "\n") {
		parts := strings.Split(strings.TrimSpace(row), "\t")
		if len(parts) < 2 {
			continue
		}
		file := parts[len(parts)-1]
		if !strings.HasSuffix(file, ".go") || strings.HasSuffix(file, "_test.go") {
			continue
		}
		body, err := os.ReadFile(file)
		if err != nil {
			continue
		}
		source := strings.Split(string(body), "\n")
		patch, err := git("diff", "--unified=0", mergeBase, "HEAD", "--", file)
		if err != nil {
			continue
		}
		for _, at := range addedLines(patch) {
			if at-1 < 0 || at-1 >= len(source) {
				continue
			}
			description, _ := describeMutation(source[at-1])
			if description == "" {
				continue
			}
			candidates++
			if len(planned) < maxMutants {
				planned = append(planned, mutant{File: file, Line: at, Description: description})
			}
		}
	}
	if candidates > len(planned) {
		fmt.Fprintf(os.Stderr, "::warning::%d mutable line(s) found in this change, capped at %d — %d will not be attempted this run.\n",
			candidates, maxMutants, candidates-len(planned))
	}
	if len(planned) == 0 {
		write(output, mutationReport{Schema: "constat.check-mutation/v1", BudgetSeconds: budgetSeconds})
		fmt.Printf("no mutable line found in this change's diff against %s — wrote an empty report\n", baseRef)
		return
	}

	// ---- 3. Break one line, ask the suite, put it back. ----
	started := time.Now()
	ran := []mutant{}
	stoppedEarly := false
	for _, one := range planned {
		if time.Since(started) >= time.Duration(budgetSeconds)*time.Second {
			stoppedEarly = true
			break
		}
		original, err := os.ReadFile(one.File)
		if err != nil {
			continue
		}
		source := strings.Split(string(original), "\n")
		_, mutated := describeMutation(source[one.Line-1])
		if mutated == "" {
			continue
		}
		source[one.Line-1] = mutated
		if err := os.WriteFile(one.File, []byte(strings.Join(source, "\n")), 0o644); err != nil {
			continue
		}
		one.Checks = checksAfter()
		// Restored before the NEXT mutant is even considered — never left broken across an error,
		// a timeout, or the budget stopping the loop right after this one.
		os.WriteFile(one.File, original, 0o644)
		if one.Checks == nil {
			one.Checks = []check{}
		}
		ran = append(ran, one)
	}

	// Belt and braces: the tree this script leaves behind is really the tree it found, which the
	// per-mutant restore above already promises. Never fatal — a mismatch here is louder evidence
	// of a bug in the loop above than a reason to fail the whole job silently.
	if status, _ := git("status", "--porcelain", "--untracked-files=no"); strings.TrimSpace(status) != "" {
		fmt.Fprintf(os.Stderr, "::warning::working tree not clean after the mutation run — restoring: %s\n", status)
		git("checkout", "--", ".")
	}

	write(output, mutationReport{
		Schema:           "constat.check-mutation/v1",
		PlannedMutants:   len(planned),
		AttemptedMutants: len(ran),
		StoppedEarly:     stoppedEarly,
		BudgetSeconds:    budgetSeconds,
		Mutants:          ran,
	})
	early := ""
	if stoppedEarly {
		early = " (stopped early at the time budget)"
	}
	fmt.Printf("ran %d of %d planned mutant(s)%s -> %s\n", len(ran), len(planned), early, output)
}
